  "perm.commands.destructive.label": "Destructive commands",
  "perm.commands.detail": "Runs app commands and registers its own commands (danger-classified commands excluded).",
  "perm.commands.inject.detail": "Runs injection commands such as sending terminal input and evaluating browser scripts.",
  "perm.commands.inject.label": "Input injection",
  "perm.commands.label": "Run and register commands",
  "perm.data.detail": "Stores and searches records in this plugin's own namespace of the shared embedded DB (SQLite), CJK full-text search included. No access to another plugin's data.",
  "perm.data.label": "Database",
  "perm.fs.read.detail": "Reads a file at any path on disk.",
