  "perm.fs.write.detail": "Writes a file at any path on disk.",
  "perm.fs.write.label": "Write files",
  "perm.network.detail": "Direct network access from the isolated document is blocked; outbound requests go through allowed host network operations.",
  "perm.network.label": "Network",
  "perm.notify.detail": "Shows OS notifications (mobile-style push while the app is inactive) and in-app banners, and plays a sound. A click on a notification opens a location inside the app (deep link).",
  "perm.notify.label": "Notifications and push",
  "perm.process.detail": "Spawns any external program as a subprocess and exchanges stdin/stdout/stderr (strongest — effectively arbitrary code execution). For integrating external tools such as LSP, MCP, and ACP.",
  "perm.process.label": "Run external programs",
  "perm.programs.detail": "Adds programs to the new-tab (+) menu. Picking one auto-runs that program's command in a terminal, including the installer when the program is missing.",
  "perm.programs.label": "Program registration",
  "perm.pty.detail": "Opens PTY-backed shell/terminal sessions and exchanges input and output (flow control and shell environment injection included — effectively arbitrary shell command execution).",
  "perm.pty.label": "Run terminal sessions",
  "perm.schedule.detail": "Schedules app commands to run automatically at a fixed time, an interval, a cron expression, or a state change (restored after an app restart). Commands run without user action.",
  "perm.schedule.label": "Scheduler",
  "perm.secrets.detail": "Stores sensitive values such as API keys and tokens in an encrypted vault. Plaintext is not kept in app data, backups, or logs, and a stored value cannot be read back in plaintext (injection only).",
  "perm.secrets.label": "Secret storage",
  "perm.service.detail": "The app spawns a resident native process that implements this plugin's commands and routes those commands to it (native code execution — resident while the app runs). Only the sidecar binary in the manifest service declaration is executed.",
  "perm.service.label": "Run a resident service",
  "perm.sidecar.detail": "Loads a shared native engine module (sidecar dylib) into the app process and exchanges messages (native code execution — strongest class). Only modules declared in the manifest sidecars[] can be opened.",
  "perm.sidecar.label": "Load a native engine module",
  "perm.storage.detail": "Stores data in this plugin's own folder (~/.soksak/plugins-data).",
  "perm.storage.label": "Private storage",
  "perm.terminal.detail": "Receives which commands start and finish in a terminal, command line and working directory included.",
  "perm.terminal.label": "Observe terminal commands",
  "perm.terminal.read.detail": "Reads the screen text of a terminal pane (the full output of the running program) and subscribes to updates (stronger than command observation).",
  "perm.terminal.read.label": "Read the terminal screen",
  "perm.terminal.write.detail": "Injects key input into a terminal pane (typing into the running program — shell commands can be run).",
  "perm.terminal.write.label": "Send terminal input",
  "perm.ui.detail": "Renders its own screen in the sidebar and content areas (the host controls placement — safe).",
  "perm.ui.label": "Content view",
  "perm.ui.overlay.pane.detail": "Provides an isolated overlay over one content pane. It starts hidden; the host controls visibility and input.",
  "perm.ui.overlay.pane.label": "Pane overlay",
  "perm.ui.overlay.screen.detail": "Provides an isolated layer over the whole app. It starts hidden; the host controls visibility and input (most invasive).",
